const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {createRequire}=require('node:module');
const req=createRequire(path.resolve('packages/infrastructure/package.json'));
const Database=req('better-sqlite3');
const {SqliteWorkspaceRepository}=require('../a-built/a-index.cjs');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const err=e=>e?{name:e.name,message:e.message,lineage:e.lineage??null}:null;
const dir=__dirname;
(async()=>{
 const A=await import('./a-migrations.mjs'),C=await import('./c-migrations.mjs'),B=await import('./b-migrations.mjs');
 const readIdentify=db=>{try{return {data:A.identify(db),error:null};}catch(e){return {data:null,error:err(e)};}};
 const report={status:'running',scope:'Focused native validation of unmodified fixed A production migrate and repository; synthetic memory/file DB only, not complete C matrix or desktop acceptance',ACommit:'41f0cdc4d2d8db931f00f4c2fc141e4274abf82b',CCommit:'45fa03d57d6fc405c2438c3b187f87838355a88b',BCommit:'6c76fb991f3135d6a48362c1b242e46af6641817',environment:{platform:process.platform,arch:process.arch,node:process.version,electron:process.versions.electron,sqlite:new Database(':memory:').prepare('select sqlite_version() v').get().v},sourceFiles:JSON.parse(fs.readFileSync(path.join(dir,'sources.json'),'utf8')),sqlFingerprints:A.MIGRATION_STEPS.map(s=>({id:s.lineage+':'+s.version,sha256:sha(s.sql.replace(/\r\n/g,'\n'))})),cases:[]};
 const emit=()=>fs.writeFileSync(path.join(dir,'report.json'),JSON.stringify(report,null,2)+'\n');
 const schema=db=>({version:db.pragma('user_version',{simple:true}),objects:db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name").all(),rows:db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all().map(({name})=>({table:name,rows:db.prepare('SELECT * FROM "'+name.replaceAll('"','""')+'" ORDER BY rowid').all()}))});
 const seed=(db,n)=>C.migrate(db,C.migrations.slice(0,n));
 const apply=db=>{try{A.migrate(db);return null;}catch(e){return err(e);}};
 function run(id,expected,fn){let result;try{result=fn();}catch(e){result={expectationMet:false,harnessError:err(e)};}report.cases.push({id,expected,...result});emit();}
 for(const n of [0,5,6,7])run('N'+String([0,5,6,7].indexOf(n)+1).padStart(2,'0')+'_C'+n+'_upgrade','upgrade to full unified 8; old rows preserved; reopen idempotent',()=>{
  const db=new Database(':memory:');if(n)seed(db,n);
  if(n){db.prepare('INSERT INTO workspace VALUES(1,?,?,1,?)').run('00000000-0000-4000-8000-000000000001','SYNTHETIC_WORKSPACE','2026-10-23T00:00:00.000Z');db.prepare('INSERT INTO idempotency VALUES(?,?,?)').run('synthetic-key','synthetic-hash','{"synthetic":"immutable UTF-8 保留"}');}
  const before=schema(db),error=apply(db),after=schema(db),firstRegistry=db.prepare('SELECT * FROM migration_registry ORDER BY lineage,version').all(),reopenError=apply(db),secondRegistry=db.prepare('SELECT * FROM migration_registry ORDER BY lineage,version').all();
  const preserved=before.rows.every(x=>JSON.stringify(after.rows.find(y=>y.table===x.table)?.rows)===JSON.stringify(x.rows));const identification=A.identify(db);db.close();return {before,after,error,reopenError,oldSqlSentinelRowsPreserved:preserved,registryRows:firstRegistry,registryStable:JSON.stringify(firstRegistry)===JSON.stringify(secondRegistry),identification,expectationMet:!error&&!reopenError&&after.version===8&&preserved&&identification.lineage==='unified'&&firstRegistry.length===9&&JSON.stringify(firstRegistry)===JSON.stringify(secondRegistry)};
 });
 run('N05_B7_upgrade','B actual v7 with legacy ledger upgrades; old ledger preserved',()=>{const db=new Database(':memory:');B.migrate(db);const before=schema(db),legacy=db.prepare('SELECT * FROM schema_migration ORDER BY version').all(),error=apply(db),after=schema(db),same=JSON.stringify(legacy)===JSON.stringify(db.prepare('SELECT * FROM schema_migration ORDER BY version').all());db.close();return {before,after,error,legacyUnchanged:same,expectationMet:!error&&after.version===8&&same};});
 run('N06_missing_report_trigger','reject missing report immutable trigger without schema/version/row changes',()=>{const db=new Database(':memory:');B.migrate(db);db.exec('DROP TRIGGER quote_check_report_no_delete');const before=schema(db),error=apply(db),after=schema(db);db.close();return {before,after,error,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 run('N07_missing_run_required_column','reject renamed required request_hash before writes',()=>{const db=new Database(':memory:');seed(db,7);db.exec('ALTER TABLE agent_run RENAME COLUMN request_hash TO synthetic_wrong_hash');const before=schema(db),identification=readIdentify(db),error=apply(db),after=schema(db);let queryError=null;try{db.prepare('SELECT request_hash FROM agent_run').all();}catch(e){queryError=err(e);}db.close();return {before,after,identification,error,postUpgradeQueryError:queryError,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 run('N08_noop_immutable_trigger','reject same-name ineffective immutable trigger',()=>{const db=new Database(':memory:');seed(db,7);db.exec('DROP TRIGGER agent_tool_step_no_delete; CREATE TRIGGER agent_tool_step_no_delete BEFORE DELETE ON agent_tool_step BEGIN SELECT 1; END;');const before=schema(db),identification=readIdentify(db),error=apply(db),after=schema(db);let deletionSucceeded=false;if(!error){const rid='00000000-0000-4000-8000-000000000002',wid='00000000-0000-4000-8000-000000000003',key='synthetic-op';db.prepare('INSERT INTO workspace VALUES(1,?,?,1,?)').run(wid,'SYNTHETIC','2026-10-23T00:00:00.000Z');db.prepare('INSERT INTO agent_run(run_id,workspace_id,operation_key,request_hash,data_json) VALUES(?,?,?,?,?)').run(rid,wid,key,'synthetic-hash',JSON.stringify({runId:rid,operationKey:key,status:'queued'}));db.prepare('INSERT INTO agent_tool_step VALUES(?,?,?,?,?)').run('00000000-0000-4000-8000-000000000002',1,'synthetic-call',1,'{}');db.exec('DELETE FROM agent_tool_step');deletionSucceeded=db.prepare('SELECT COUNT(*) n FROM agent_tool_step').get().n===0;}db.close();return {before,after,identification,error,syntheticStepDeletionSucceeded:deletionSucceeded,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 run('N09_nonunique_write_index','reject same-name nonunique write-once index',()=>{const db=new Database(':memory:');seed(db,7);db.exec('DROP INDEX agent_write_once; CREATE INDEX agent_write_once ON agent_write_call(run_id,attempt)');const before=schema(db),identification=readIdentify(db),error=apply(db),after=schema(db),index=db.pragma('index_list(agent_write_call)').find(x=>x.name==='agent_write_once');db.close();return {before,after,identification,error,index,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 run('N10_corrupt_registry_preflight','corrupt new registry hash rejected during readonly preflight, before database byte/journal changes',()=>{
  const root=path.join(dir,'registry-case-'+crypto.randomUUID());fs.mkdirSync(root,{recursive:true});const file=path.join(root,'synthetic.sqlite');
  if(fs.existsSync(file))throw Error('dedicated fixture must be fresh');let db=new Database(file);A.migrate(db);db.prepare('UPDATE migration_registry SET sql_hash=? WHERE lineage=? AND version=?').run('0'.repeat(64),'common',1);db.pragma('journal_mode=DELETE');const before=schema(db);db.close();
  const hashBefore=sha(fs.readFileSync(file)),filesBefore=fs.readdirSync(root).sort();db=new Database(file,{readonly:true});let readonlyError=null,readonlyIdentification;try{readonlyIdentification=A.identify(db);}catch(e){readonlyError=err(e);}db.close();
  let repositoryError=null,repository;try{repository=new SqliteWorkspaceRepository(file);}catch(e){repositoryError=err(e);}finally{repository?.close();}
  const hashAfter=sha(fs.readFileSync(file)),filesAfter=fs.readdirSync(root).sort();db=new Database(file,{readonly:true});const after=schema(db),journalAfter=db.pragma('journal_mode',{simple:true});db.close();return {before,after,readonlyIdentification,readonlyError,repositoryError,fileHashBefore:hashBefore,fileHashAfter:hashAfter,filesBefore,filesAfter,journalModeBefore:'delete',journalModeAfter:journalAfter,expectationMet:!!readonlyError&&!!repositoryError&&hashBefore===hashAfter&&journalAfter==='delete'};
 });
 run('N11_legacy_ledger_schema_contradiction','reject legacy ledger claiming knowledge6 when actual schema is C7 without knowledge tables',()=>{const db=new Database(':memory:');seed(db,7);db.exec('CREATE TABLE schema_migration(version INTEGER PRIMARY KEY,sql_hash TEXT NOT NULL)');for(const s of B.migrations.filter(s=>s.version!==7))db.prepare('INSERT INTO schema_migration VALUES(?,?)').run(s.version,sha(s.sql.replace(/\r\n/g,'\n')));const before=schema(db),identification=readIdentify(db),error=apply(db),after=schema(db);db.close();return {before,after,identification,error,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 run('N12_bad_sql_rollback','actual migrate invalid appended SQL rolls back all DDL/registry/version',()=>{const db=new Database(':memory:');seed(db,7);const before=schema(db);let error=null;try{A.migrate(db,[...A.MIGRATION_STEPS,{lineage:'common',version:99,sql:'CREATE TABLE synthetic_partial(id TEXT); INVALID SQL;'}]);}catch(e){error=err(e);}const after=schema(db);db.close();return {before,after,error,expectationMet:!!error&&JSON.stringify(before)===JSON.stringify(after)};});
 report.summary={total:report.cases.length,passed:report.cases.filter(x=>x.expectationMet).length,failed:report.cases.filter(x=>!x.expectationMet).map(x=>x.id)};report.status=report.summary.failed.length?'failed':'passed';report.compatible=false;report.scriptUtf8=fs.readFileSync(__filename,'utf8');report.recordedAt=new Date().toISOString();emit();console.log(JSON.stringify({status:report.status,environment:report.environment,summary:report.summary,cases:report.cases.map(x=>({id:x.id,expectationMet:x.expectationMet,error:x.error??x.repositoryError??null,harnessError:x.harnessError??null}))}));process.exitCode=report.summary.failed.length?1:0;
})().catch(e=>{console.error(e);process.exitCode=2;});
